CREATE TABLE public.meal_foods (id text PRIMARY KEY, owner_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL, portions jsonb NOT NULL, nutrition jsonb NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.meal_foods TO service_role;
ALTER TABLE public.meal_foods ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meal_food_searches (query text PRIMARY KEY, food_ids text[] NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.meal_food_searches TO service_role;
ALTER TABLE public.meal_food_searches ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meal_food_recent (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, food_id text REFERENCES public.meal_foods(id) ON DELETE CASCADE, used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,food_id));
GRANT ALL ON public.meal_food_recent TO service_role;
ALTER TABLE public.meal_food_recent ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.meal_usda_budget (hour timestamptz PRIMARY KEY, requests integer NOT NULL DEFAULT 0);
GRANT ALL ON public.meal_usda_budget TO service_role;
ALTER TABLE public.meal_usda_budget ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_meal_usda_request() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.meal_usda_budget(hour,requests) VALUES(date_trunc('hour',now()),1) ON CONFLICT(hour) DO UPDATE SET requests=meal_usda_budget.requests+1 WHERE meal_usda_budget.requests<600 RETURNING requests INTO n; RETURN n IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.claim_meal_usda_request() FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_meal_usda_request() TO service_role;
ALTER TABLE public.meals ADD COLUMN source_meal_id uuid;
ALTER TABLE public.meals ADD COLUMN source_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public.meals ADD COLUMN source_name text;
ALTER TABLE public.meals ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE UNIQUE INDEX meals_source_copy ON public.meals(user_id,source_meal_id) WHERE source_meal_id IS NOT NULL;
REVOKE ALL ON public.meals FROM authenticated;
GRANT SELECT(id,user_id,source_post_id) ON public.meals TO authenticated;
CREATE TABLE public.meal_attachments (kind text NOT NULL CHECK(kind IN('post','checkin')), content_id uuid NOT NULL, owner_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, snapshot jsonb NOT NULL, PRIMARY KEY(kind,content_id));
GRANT ALL ON public.meal_attachments TO service_role;
ALTER TABLE public.meal_attachments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.meal_without_numbers(j jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF j IS NULL THEN RETURN NULL; END IF; IF jsonb_typeof(j)='array' THEN SELECT coalesce(jsonb_agg(public.meal_without_numbers(value)),'[]') INTO result FROM jsonb_array_elements(j); RETURN result; ELSIF jsonb_typeof(j)='object' THEN SELECT coalesce(jsonb_object_agg(key,public.meal_without_numbers(value)),'{}') INTO result FROM jsonb_each(j) WHERE key NOT IN('calories','protein','carbs','fat','nutrition','totals','override','missingCalories'); RETURN result; END IF; RETURN j; END $$;
INSERT INTO public.meal_attachments(kind,content_id,owner_id,snapshot) SELECT 'post',id,user_id,meal FROM public.social_posts WHERE meal IS NOT NULL;
UPDATE public.social_posts SET meal=public.meal_without_numbers(meal) WHERE meal IS NOT NULL;
CREATE FUNCTION public.protect_social_meal_numbers() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.meal:=public.meal_without_numbers(NEW.meal); RETURN NEW; END $$;
CREATE TRIGGER protect_social_meal_numbers BEFORE INSERT OR UPDATE OF meal ON public.social_posts FOR EACH ROW EXECUTE FUNCTION public.protect_social_meal_numbers();
ALTER TABLE public.check_ins ADD COLUMN meal_id uuid;
CREATE FUNCTION public.snapshot_checkin_meal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meals; BEGIN IF NEW.meal_id IS NULL THEN RETURN NEW; END IF; IF NOT public.is_new_version_user(NEW.user_id) THEN RAISE EXCEPTION 'Not available'; END IF; SELECT * INTO m FROM public.meals WHERE id=NEW.meal_id AND user_id=NEW.user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Meal unavailable'; END IF; INSERT INTO public.meal_attachments(kind,content_id,owner_id,snapshot) VALUES('checkin',NEW.id,NEW.user_id,m.snapshot||jsonb_build_object('mealId',m.id,'fromName',m.source_name)); RETURN NEW; END $$;
CREATE TRIGGER snapshot_checkin_meal AFTER INSERT ON public.check_ins FOR EACH ROW EXECUTE FUNCTION public.snapshot_checkin_meal();
CREATE FUNCTION public.create_library_meal_post(_meal_id uuid,_caption text,_audience text,_group_ids uuid[],_items jsonb,_workout jsonb,_workout_session_id uuid,_workout_id uuid,_credit_user_id uuid,_comments_on boolean,_tags uuid[],_skip_discover boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.meals; p uuid; BEGIN SELECT * INTO m FROM public.meals WHERE id=_meal_id AND user_id=auth.uid(); IF NOT FOUND OR NOT public.is_new_version_user(auth.uid()) THEN RAISE EXCEPTION 'Meal unavailable'; END IF; p:=public.create_library_post_v2(_caption,_audience,_group_ids,_items,_workout,_workout_session_id,_workout_id,_credit_user_id,_comments_on,_tags,_skip_discover); INSERT INTO public.meal_attachments(kind,content_id,owner_id,snapshot) VALUES('post',p,auth.uid(),m.snapshot||jsonb_build_object('mealId',m.id,'fromName',m.source_name)); UPDATE public.social_posts SET meal=public.meal_without_numbers(m.snapshot||jsonb_build_object('mealId',m.id,'fromName',m.source_name)) WHERE id=p; RETURN p; END $$;
REVOKE ALL ON FUNCTION public.create_library_meal_post(uuid,text,text,uuid[],jsonb,jsonb,uuid,uuid,uuid,boolean,uuid[],boolean) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.create_library_meal_post(uuid,text,text,uuid[],jsonb,jsonb,uuid,uuid,uuid,boolean,uuid[],boolean) TO authenticated;
CREATE FUNCTION public.cleanup_meal_attachment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.meal_attachments WHERE content_id=OLD.id AND kind=CASE WHEN TG_TABLE_NAME='social_posts' THEN 'post' ELSE 'checkin' END; RETURN OLD; END $$;
CREATE TRIGGER cleanup_post_meal AFTER DELETE ON public.social_posts FOR EACH ROW EXECUTE FUNCTION public.cleanup_meal_attachment();
CREATE TRIGGER cleanup_checkin_meal AFTER DELETE ON public.check_ins FOR EACH ROW EXECUTE FUNCTION public.cleanup_meal_attachment();